    footL: "Tinkazo", footR: "Hecho con ♥ en Bolivia",
    builtOn: "Hecho con",
    // `seed` es la barra de arriba del sorteo: "NÚMERO PÚBLICO N.º 32254977".
    // Decía "· RONDA", que es la palabra de drand, y en el sorteo no va nada
