    maHeroAlt: "Lo que trae el kit de marca de Tinkazo: logos, stickers, afiches e imágenes para redes",
    maLlama: "La llama, sin fondo",
    maLlamaB: "En el logo, la llama es una silueta pixelada, sin cara ni ojos: conservá sus proporciones y no le agregues sombrero, poncho ni otros detalles. En los stickers sale en sus días buenos, con un corazón, banderines o confeti, y sigue sin cara. Las dos vienen con fondo transparente, y los PNG miden 2048 píxeles por lado.",
