    maNo6: "Comillas angulares, las de apertura y las de cierre, en español y en inglés. Un botón, una pestaña o un modo se escribe tal como se ve en la pantalla y sin comillas: <em>Tocá <strong>Sellar la lista</strong>.</em> Si se puede, el nombre va en negrita.",
