    maStB: "Archivos a tamaño real, listos para la imprenta: de 5 y de 7 cm, con 3 mm de sangrado. La línea de corte va en una capa aparte, llamada corte, que se puede ocultar. Imprimí en vinilo mate. Los colores son RGB: la imprenta los convierte.",
