    maDescT: "Cómo se describe Tinkazo",
    maDescL: "Tinkazo: sorteos que cualquiera puede comprobar",
    maDescP: "Tinkazo cierra la lista de participantes antes de sortear, así nadie puede cambiarla después. El ganador sale de un número público que nadie conoce de antemano, y cualquiera puede repetir la cuenta y comprobar el resultado. Participar es gratis, siempre.",
