    maColB: "Veintiocho stickers para pegar en la laptop o regalar en un evento: los diez juegos numerados del 1 al 10 para completar la colección, el especial de Tarija, la llama en sus días buenos, frases nuestras y una tanda para quienes programan. Cada uno se elige: no hay sobres sorpresa.",
    maColNota: "Vienen troquelados por su silueta, con borde blanco, 3 mm de sangrado y la capa de corte. La medida mayor es de 5 o de 7 cm y las frases se leen bien a 5 cm. Todos llevan tinkazo.app en una etiqueta chica abajo, del mismo tamaño en todos. Los PNG tienen fondo transparente, para redes o para un video.",
