    maSpT: "Si nos ponés de sponsor",
    maSpB: "Lo que suelen pedir los organizadores, en un solo lugar: el logo para la pared de sponsors, la descripción en tres largos, textos para redes e imágenes para anunciarlo. Se copia o se baja sin pedirnos nada.",
    maSpZip: "Descargar el kit para sponsors (ZIP)",
    maSpZipNota: "Los logos para la pared de sponsors (también en PDF y en PNG de 2400 px), seis imágenes para redes, todos los textos y cinco preguntas para coordinar, en español y en inglés. Pesa 2,7 MB.",
    maSpNombreT: "Cómo se escribe",
    maSpNombre: "Tinkazo, todo junto, con K y con la T mayúscula. Nunca Tincazo, TinkaZo ni Tinkazo App.",
    maSpLogosT: "El logo para la pared de sponsors",
    maSpLogosB: "En una caja fija con aire alrededor, para que quede del mismo tamaño que los demás: horizontal de 1200 × 600 y cuadrado de 800 × 800, en PNG transparente y en SVG. Para una pared impresa, el PNG de 2400 px o el PDF, que se agranda sin perder nada.",
