    maMonoAltCB: "Logo de Tinkazo de un solo color: cuadrado, blanco",
    maSpDescT: "La descripción, en tres largos",
    maSp25T: "En 25 palabras, para el programa",
    maSp50T: "En 50 palabras, para la web del evento",
    maSp100T: "En 100 palabras, para la presentación de sponsors",
    maSpD25: "Tinkazo hace sorteos que cualquiera puede comprobar. La lista se cierra antes de sortear y el ganador sale de un número público. Participar es gratis.",
    maSpD50: "Tinkazo es una herramienta boliviana para hacer sorteos que cualquiera puede comprobar. Quien organiza pega la lista, Tinkazo la cierra antes de sortear y el ganador sale de un número público que nadie conoce antes. El resultado se cuenta en pantalla con juegos de Bolivia, como la carrera de llamas.",
    maSpD100: "Tinkazo es una herramienta boliviana para hacer sorteos que cualquiera puede comprobar, pensada para comunidades, meetups, clases y eventos. Quien organiza pega la lista de participantes y Tinkazo la cierra antes de sortear, así nadie puede cambiarla después. El ganador sale de un número público que nadie conoce de antemano, y cualquiera puede repetir la cuenta desde un enlace o un QR. El resultado se cuenta en la pantalla con diez juegos de Bolivia, como la carrera de llamas, el Guajojó, el Toborochi o La Entrada. Participar en un sorteo es gratis, siempre. Más en tinkazo.app y en Instagram, @tinkazo.app.",
    maCopiar: "Copiar",
    maCopiadoBtn: "Copiado",
    maSpPostT: "Tres textos para redes, sugeridos para que publiquen los organizadores",
    maSpPostSug: "Son textos sugeridos para que los publiquen los organizadores: cambialos como quieras. Si acordamos algo más (un sorteo o un lugar en el evento), sumalo.",
    maSpPost1T: "Cuando se anuncia",
    maSpPost2T: "El día del evento",
    maSpPost3T: "Para agradecer",
    maSpPost1: "Damos la bienvenida a Tinkazo como sponsor del DevFest Tarija. Tinkazo hace sorteos que cualquiera puede comprobar: la lista se cierra antes de sortear y el ganador sale de un número público. Conocelos en tinkazo.app y en @tinkazo.app",
    maSpPost2: "Tinkazo, sponsor del DevFest Tarija, hace sorteos que cualquiera puede comprobar. Probá uno con tus amigos en tinkazo.app y comprobá el resultado vos mismo. Gracias, @tinkazo.app",
    maSpPost3: "Gracias a Tinkazo por acompañarnos como sponsor del DevFest Tarija. En sus sorteos, cada ganador se puede comprobar desde el enlace del sorteo. Seguilos en @tinkazo.app",
    maSpPostNota: "Sumá las etiquetas del evento. Decí sorteo, no rifa. Entrar a un sorteo de Tinkazo es gratis.",
    maSpImgT: "Imágenes para anunciarlo, en dos estilos",
    maSpImgB: "Anuncian que Tinkazo es sponsor del DevFest Tarija, con la fecha (28 de noviembre de 2026), el logo y @tinkazo.app. Elegí el estilo: con cuatro personajes de nuestros stickers o con capturas de los juegos. En PNG, en claro y oscuro, en español o en inglés según el idioma de la página.",
    maSpEstP: "Con los personajes de los stickers",
    maSpEstJ: "Con los juegos",
    maSpEstJB: "Capturas de seis juegos, cada una con su nombre. Se bajan de a una: con fotos pesan más y no van en el ZIP.",
    maSpImg5: "Panorámica para la web o LinkedIn, 1200 × 675",
    maSpImg6: "Banner ancho para la web del evento, 1980 × 400",
    maSpPregT: "Para coordinar, cinco preguntas",
    maSpPregB: "Si nos mandás las respuestas a hola@tinkazo.app, preparamos las piezas a la medida de tu evento.",
    maSpPreg1: "¿En qué formato y tamaño necesitan el logo, y para qué fecha?",
    maSpPreg2: "¿Qué largo tiene la descripción del programa o de la web del evento?",
    maSpPreg3: "¿Cómo quieren que nombremos al evento en redes, y con qué etiquetas?",
    maSpPreg4: "¿Habrá un lugar para nosotros (mesa, pared o roll-up) y a qué hora se arma?",
    maSpPreg5: "¿Quieren hacer algún sorteo del evento con Tinkazo? Entrar es gratis, siempre.",
    maSpPregTxt: "Las preguntas en un archivo (TXT)",
    maSpImg1: "Publicación de Instagram, 1080 × 1350",
    maSpImg2: "Historia de Instagram, 1080 × 1920",
    maSpImg3: "Cabecera de LinkedIn, 1584 × 396",
    maSpImg4: "Cabecera de X, 1500 × 500",
    maImpT: "Para el stand: roll-up y banner de mesa",
    maImpB: "Los archivos que llevamos a los eventos, listos para la imprenta. El roll-up viene en 85 y en 100 cm de ancho por 200 de alto, y el banner para el frente de la mesa en 120 por 40 cm. Traen fotos de los juegos, los personajes de los stickers, el QR grande a tinkazo.app e Instagram. Para algo chico arriba de la mesa, el cartel A5 o el afiche A3 de más abajo.",
    maImpNota: "Llevan 5 mm de sangrado. En el roll-up, los 15 cm de abajo quedan libres porque los tapa la base, y el código QR mide 32,5 cm de lado (43,5 con su borde blanco): se escanea desde unos 3 m. En el banner, texto y QR quedan a 6 cm de cada borde, para el dobladillo y los ojales. Antes de imprimir, pedile a la imprenta su plantilla: algunas piden 3 o 10 mm de sangrado. El SVG enlaza las fotos de los juegos, y el ZIP de abajo las trae al lado.",
    maImpColor: "Los colores están en RGB: la imprenta los pasa a CMYK y el turquesa y el morado pueden salir más apagados. Pedí una prueba de color antes de imprimir todo, y escaneá el QR de la prueba con un celular.",
    maImpZip: "Descargar los SVG con sus fotos (ZIP)",
    maImpZipNota: "Para editar el roll-up y el banner de mesa: los seis SVG con las seis fotos de los juegos que enlazan. Los PDF para la imprenta se bajan de a uno, arriba.",
    maImpRoll: "Roll-up",
    maImpMesa: "Banner para el frente de la mesa, 120 × 40 cm",
