    vVerdictOkChainDetailTest: "Lo rehicimos acá y coincide con lo que quedó grabado en el contrato. Está en testnet, la red de pruebas de Stellar, que se borra entera el 16 de diciembre de 2026: hasta entonces, cualquiera puede leer ese registro.",
    vChainMissing: "el contrato no tiene ese sorteo",
    vVerdictMissing: "No está en la cadena",
    vVerdictMissingDetail: "Las cuentas cierran, pero el contrato no tiene registrado este sorteo. Puede ser una red de pruebas borrada (testnet se borra el 16 de diciembre de 2026), un registro archivado o un número que no existe. Para comprobarlo en el historial de Stellar hace falta el código de la transacción del sello, y los enlaces más antiguos no lo traen. Sin ese registro, nadie atestigua que esta sea la lista sellada.",
