    vVerdictPending: "Sellado en Stellar, falta grabar el resultado",
    vVerdictPendingDetail: "La lista quedó sellada en Stellar antes de que existiera el número, y con ese número el ganador es el que ves. Falta que el resultado quede grabado: cualquiera puede hacerlo, y sale el mismo.",
