    vVerdictSealedAgain: "Cuadra, pero esta lista se selló más de una vez",
    vVerdictSealedAgainDetail: "Lo que quedó grabado en el contrato coincide, pero la misma lista tiene otros sellos (están más abajo). Puede tener una explicación, pero también es la forma de probar varias veces y publicar solo el resultado que conviene: pedí los comprobantes de todos.",
    vSealsNear: "otra cuenta, la misma cantidad de gente, casi a la misma hora",
    vSealsNearWhy: "Otra cuenta selló, casi a la misma hora, un sorteo con la misma cantidad de gente. Puede ser otro evento, pero también puede ser la misma lista en otro orden, sellada desde otra cuenta para quedarse con el resultado que convenía. Si te importa, pedí los comprobantes de los dos.",
    vRetiredDetail: "El enlace apunta a un registro que Tinkazo ya no usa, y el sorteo se selló ahí después de que se dejó de usar. Ese registro sigue abierto y cualquiera puede sellar en él, así que no prueba nada.",
    vTechContratoRetirado: "El contrato {c} dejó de ser el del sitio con el sorteo {n}, y este sorteo es el {id}.",
    // Cuando el contrato ya no guarda el sorteo, el sello se comprueba con el historial de Stellar (protocolo §7.1).
    // {m} es una de las dos primeras: la memoria rápida de la red ya no guarda el sorteo (se archivó) o no se pudo leer ahora.
    vVerdictOkHistoryDetail: "{m}. Se comprobó con su historial público de Stellar: el sello es del {f} (código {c}) y el número público salió después. Lo rehicimos acá y da el mismo nombre, así que nadie pudo elegir el resultado. El número de sorteo que trae el enlace no se puede comprobar por este camino: el sorteo se reconoce por esa fecha y ese código.",
    vVerdictOkHistoryDetailTest: "{m}. Se comprobó con su historial público de Stellar: el sello es del {f} (código {c}) y el número público salió después. Lo rehicimos acá y da el mismo nombre, así que nadie pudo elegir el resultado. El número de sorteo que trae el enlace no se puede comprobar por este camino: el sorteo se reconoce por esa fecha y ese código. Está en testnet, la red de pruebas de Stellar, que se borra entera el 16 de diciembre de 2026.",
    vHistMemoriaArchivada: "Este sorteo ya no está en la memoria rápida de la red",
    vHistMemoriaSinLeer: "No pude leer este sorteo en la memoria rápida de la red",
    vTx: "Ver el sello en Stellar ↗",
    vOfficialAddress: "su dirección es de Tinkazo",
    vChainFromHistory: "el sello está en el historial público",
    vHistInvalidDetail: "El enlace cita una transacción de Stellar que no es el sello de este sorteo.",
    vHistDistinctDetail: "Lo que guarda el contrato y lo que dice el historial público de Stellar no coinciden en este sorteo, y los dos tienen que decir lo mismo.",
    // Por qué el historial no pudo confirmar un sorteo que el contrato ya no guarda. Ninguna dice que no exista.
    vHistWhyDown: "El contrato ya no guarda este sorteo y no pude consultar el historial público de Stellar, donde puede seguir estando. No quiere decir que no exista: probá de nuevo en unos minutos.",
    vHistWhyOdd: "El contrato ya no guarda este sorteo y el historial público de Stellar contestó algo que no pude entender. Puede ser un corte momentáneo: probá de nuevo en unos minutos.",
    vHistWhyWindow: "El contrato ya no guarda este sorteo y el historial público de Stellar que consulto ya no guarda operaciones tan antiguas. Eso no quiere decir que el sorteo no exista, solo que desde acá no puedo comprobarlo. La historia completa de Stellar está en sus archivos de historia y en exploradores como stellar.expert: ahí se puede comprobar la transacción del sello, y en los detalles técnicos está cómo.",
    vHistWhyNone: "El contrato ya no guarda este sorteo y el historial público de Stellar que consulto no tiene esa transacción. Puede ser que ya no la guarde o que el enlace tenga un error: no puedo decir ni que existió ni que no. Un explorador como stellar.expert o los archivos de historia de Stellar pueden confirmarlo, y en los detalles técnicos está cómo.",
