    claseW3B: "Students install nothing and create no account. Only the person running the draw signs in.",
    clasePrivT: "Privacy",
    clasePrivB: "The names stay in the browser of whoever runs the draw and are not published. When you share or show it big, a copy is also kept for the short link, which only opens with the link: Tinkazo can't read it. But anyone with the link, the photo or the QR code on the screen sees the whole list: better it doesn't leave the class, especially if there are minors. If that copy needs to be deleted, write to hola@tinkazo.app.",
    verifKicker: "To check it",
    verifH1: "Verifiable draw: anyone can redo the result",
    verifLead: "A verifiable draw leaves the evidence in plain sight. Here is what gets checked, who checks it and what it doesn't promise yet.",
    verifIdeaT: "The idea in three sentences",
    verifI1T: "First, the list",
    verifI1B: "The list is sealed before the number that decides exists.",
    verifI2T: "Then, the number",
    verifI2B: "The number is published by a network of independent organizations, and neither the organizer nor Tinkazo can pick it.",
    verifI3T: "Finally, anyone can redo it",
    verifI3B: "Anyone can redo the result and must get the same name.",
    verifWhatT: "What gets checked, and who checks it",
    verifW1: "In a recorded draw: the list matches the summary recorded when it was sealed. Your phone calculates it and compares it.",
    verifW2: "The number: that it is the one published at that time. Anyone can see it online.",
    verifW3: "The winner: that it comes from the list and the number with the same math, every time. Your phone redoes it.",
    verifW4: "In a draw with an account, the seal: that it was recorded publicly, with its time. Anyone can see it in a public explorer that isn't ours.",
    verifNotT: "What it doesn't promise",
    verifN1: "Whoever runs a draw could seal the same list several times and publish only the result that suits them. That's why seals are public: the verification page shows that account's seals and flags the ones that repeat the same list. It doesn't fully prevent it: it makes it visible, but doesn't stop it.",
    verifN2: "If the organizer's browser extension is on a different network than the site, the seal is not recorded. The draw still closes, but nobody other than the organizer attests that this was the list. The page says so with a yellow verdict instead of an easy green.",
    verifN3: "Tinkazo runs in test mode today. Keep the receipt of your draws: it lets anyone check them again even after the record resets on December 16, 2026.",
    verifHowT: "How to check it yourself",
    verifHow1: "Open the receipt's link on your phone",
    verifHow1B: "The page redoes the draw by itself and tells you whether it gives the same name.",
    verifHow2: "Every step can be checked",
    verifHow2B: "The code is open and the rules of the draw are written step by step.",
    verifHow3: "The technical details are in How it works and in Security",
    verifHow3B: "You don't need them here. The home page doesn't need them either.",
    verifHowSeg: "Security and limits →",
    // --- La portada, la herramienta y Cómo funciona (3 de octubre de 2026).
