    navMas: "More",
    ctaDemo: "Watch a demo",
    pjKicker: "The show",
    pjT: "Ten reveals. None of them decides anything.",
    pjB: "Tap one and watch it draw a sample list, no account needed. They all show the same result: the show changes, not who wins.",
    pjVer: "Watch demo",
    confKicker: "Why believe it",
    confT: "You don't have to take my word for it: every step can be checked.",
    conf1t: "Anyone can check it",
    conf1b: "The list is locked before the draw, and the winner comes from a number that neither the organizer nor Tinkazo can pick. On a phone, anyone can redo the draw and must get the same winner.",
    confMas: "How it works, step by step →",
    confReal: "See a real draw, verified →",
    usosKicker: "Who it's for",
    usosT: "For whenever someone has to hand things out.",
    uso1t: "Meetups and communities",
    uso1b: "The draw at the end, with the projector on and everyone watching. You upload your Luma CSV and draw only among those who came.",
    uso2t: "Classrooms and workshops",
    uso2b: "Who presents first, who takes the book home. Without anyone saying the organizer picked a favorite.",
    uso3t: "Teams at work",
    uso3b: "Draw the year-end gift or the order of the shifts, with a result anyone can check.",
    uso4t: "Fairs and events",
    uso4b: "Prizes for the people who came, with no paperwork and no suspicion. Entering is always free.",
    faqKicker: "Questions",
    faqT: "What everybody asks.",
    faq1q: "Does anyone pay to take part?",
    faq1a: "No. We never charge anyone to take part, and the terms forbid using Tinkazo for draws with paid entry.",
    faq2q: "Do my people have to install anything?",
    faq2a: "No. Only the organizer signs in, with Google and in two taps. Participants don't install anything or sign up.",
    faq3q: "How much does it cost?",
    faq3a: "It's free for everyone today. We'll publish pricing for organizers very soon, and we'll tell you before we charge. Taking part and checking are always free.",
    faq4q: "How do I know you didn't cheat?",
    faq4a: "You don't have to believe me: the receipt carries the list and the proof, and your phone redoes the draw. If anyone tampered with it, you get a different result.",
    faq5q: "What gets saved, and where?",
    faq5a: 'Names are never published: they stay on your device and in the receipt you share. Each draw leaves only a public record, under your account and without names. <a href="/como-funciona.html#que-se-guarda">What is kept, in How it works</a>.',
