    // The list once sealed, on the projector and on the phone (Oct 21, 2026).
    salaTSellada: "The sealed list",
    salaPieSellada: "The list is sealed and can't change. Find yourself while the number comes out.",
    listaNotaSellada: "This is the sealed list: it won't change, and the winner comes from these names. Find yourself. The draw's fingerprint starts with these characters.",
    // No seal (the network wouldn't let it seal): the list is closed in the tool, but nobody attests that it is.
    salaTCerrada: "List closed, no seal",
    salaPieCerrada: "List closed, no seal: this draw can't be checked. Find yourself while the number comes out.",
    listaNotaCerrada: "This is the closed list, with no seal: this draw can't be checked. The winner comes from these names. Find yourself. The draw's fingerprint starts with these characters.",
    buscateL: "Are you on the list?",
    buscatePh: "Type your name",
    buscateUno: "You are number {p} of {n}.",
    buscateVarios: "{k} matches: numbers {p}.",
    buscateNada: "Nobody by that name.",
    buscateDos: " Heads up: that name appears {k} times.",
    listaNota: "This is the list about to be sealed. Find yourself: if someone is missing or listed twice, tell the organizer before the seal. Once sealed, the draw's fingerprint has to start with these characters.",
    listaHuellaL: "This list's fingerprint:",
    listaPremio: "Prize:",
    listaError: "This link doesn't carry a list.",
    waitId: "Draw #{n}. Write it down or take a photo",
    waitIdPagina: "Draw #{n}",
    vSealsElsewhere: "the same list, sealed by another account",
    vSealsElsewhereWhy: "Another account also sealed this same list. It may be someone who repeated the draw with another account to publish only the convenient result. Ask for the receipts of all of them.",
    cfDuraT: "What is left of your draw, and for how long",
    cfDuraB1: "What proves your draw is the seal: the transaction recorded on Stellar, with its time, when you closed the list. The receipt is yours: you keep it, you send it and you use it whenever you want to check the draw again.",
    cfDura1: "<b>Your receipt:</b> it lasts as long as you keep it. While you have it, you can redo the math whenever you want.",
    cfDura2: "<b>The contract's memory:</b> 7 days on the test network (testnet) and 120 on the main network (mainnet). It is short and it is not what proves the draw: the seal is.",
    cfDura3: "<b>The test network:</b> Tinkazo runs there today, and Stellar wipes all of it on December 16, 2026, seals and their times included. Your receipt still lets anyone redo the math, but nobody will be able to confirm the seal time.",
    cfCostoT: "For those who want the detail: what the network costs",
    cfCostoB: 'Recording each draw on the network has a cost. The network charges it, not Tinkazo, and almost all of it is storage rent: it changes with how much the network is used. Today Tinkazo pays it. The measured figures, with their dates, are in <a href="https://github.com/nema1502/tinkazo/blob/main/docs/deployments.md" target="_blank" rel="noopener">docs/deployments.md</a>.',
    cfDuraPromesa: "This receipt carries what is needed to re-check the draw with open tools. The seal time is confirmed by Stellar's public archives for as long as they exist: nobody guarantees that term, and neither do we. Keep it.",
    cfSinT: "Check it without us",
    cfSinB: "You don't need this site. With the draw number, which is in the rules and in the receipt:",
    cfSin1t: "The seal and the result, in an explorer",
    cfSin1b: "Look up the contract on stellar.expert, which isn't ours: every seal is there, with its fingerprint, its round and who won.",
    cfSin1a: "The contract on stellar.expert →",
    cfSin2t: "The number, from drand",
    cfSin2b: "drand publishes the round's signature at a public address anyone can open: api.drand.sh, the quicknet network and the round number.",
    cfSin2a: "The latest round, on drand's public API →",
    cfSin3t: "The math, by hand",
    cfSin3b: "With the list, the fingerprint and the signature, the math is written step by step in the protocol. Anyone can redo it in any language and must get the same winner.",
    cfSin3a: "The protocol, on GitHub →",
    demoBanner: "Demo with a sample list: nothing is recorded.",
    demoFinT: "Easy, right? Try it with your list.",
    cfKicker: "How it works",
    cfH1: "Five steps, and every one of them can be checked.",
    cfLead: "This is how a winner comes out in Tinkazo, without jargon. For the technical detail, see the protocol and the security page.",
    cf1t: "You bring the list",
    cf1b: "Paste the names or upload a CSV from Luma or any spreadsheet. Before sealing, you can show it to the room with a QR, so everyone can find themselves on their phone and speak up if someone is missing or listed twice. Participants need nothing.",
    cf2t: "The list gets sealed",
    cf2b: "It gets a fingerprint, like a file's: change one letter and the whole thing changes. The fingerprint and the time are recorded on Stellar.",
    cf3t: "A number from the future is picked",
    cf3b: "drand, a network of universities and companies, publishes a random number every three seconds. The draw uses one that doesn't exist yet when the list is sealed: nobody can know it in advance.",
    cf4t: "The winner comes out",
    cf4b: "When that number arrives, a contract on Stellar checks its signature and runs the calculation, always the same, that says who wins. The game on screen only tells it.",
    cf5t: "Anyone can check it",
    cf5b: "The receipt carries the list, the round and the signature. From a phone, the site redoes everything and says whether it matches. If anyone touched anything, it won't.",
    cfGuardaT: "What gets saved, and where",
    cfGuardaB: "What goes to Stellar follows your account on any device. The names don't: they stay in the browser where you sealed and in the receipt. If you share it or show it big, a copy is also kept on Cloudflare for the short link, locked with a key that travels only in the link: Tinkazo can't read it.",
    cfColQue: "What",
    cfColDonde: "Where",
    cfColQuien: "Who sees it",
    cfG1a: "The list's fingerprint, the head count and the number of winners, the prize, the round and the result (full list in Security)",
    cfG1b: "On Stellar, under your account",
    cfG1c: "Anyone",
    cfG2a: "Your draws",
    cfG2b: "In My draws, from any device you sign in from",
    cfG2c: "You, and anyone with your address",
    cfG3a: "The names",
    cfG3b: "On your device and in the receipt you share: never on the chain",
    cfG3c: "Whoever has the link",
    cfG4a: "Your key",
    cfG4b: "With Google, Pollar keeps it. With Varial (formerly Freighter), your extension. With the test account, your browser",
    cfG4c: "Nobody else",
    cfG5a: "The short link's copy, when you share or show it big",
    cfG5b: "On Cloudflare, with no expiry, so the draw can be checked again. Deleted if you ask at hola@tinkazo.app",
    cfG5c: "Anyone with the link or its QR code. Tinkazo can't read it",
    cfNoT: "What if I don't trust Tinkazo?",
    cfNoB: "The protocol is written down and the code is open: anyone can redo a draw without going through this site.",
