    maDescL: "Tinkazo: draws anyone can check",
    maDescP: "Tinkazo locks the list of participants before the draw, so no one can change it afterwards. The winner comes from a public number that nobody knows in advance, and anyone can redo the math and check the result. Taking part is always free.",
