    // The character sticker collection (marca.html#coleccion).
    maColT: "Character stickers",
    maColB: "Twenty-eight stickers for your laptop or to hand out at an event: the ten games numbered 1 to 10 to complete the collection, the Tarija special, the llama on its good days, our own sayings and a batch for people who code. You pick each one: there are no mystery packs.",
    maColNota: "They are die-cut along their outline, with a white border, 3 mm bleed and the layer named corte. The longest side is 5 or 7 cm and the sayings read well at 5 cm. Each one carries tinkazo.app on a small tag at the bottom, the same size on all of them. The PNG files have a transparent background, for social media or a video.",
