    maRedOscuro: "Download dark PNG",
    maAfT: "Posters and table sign",
    maAfB: "The event poster, in A4 and A3, with a big QR code and a strip to write the prize by hand. There is also the A5 table sign for the stand, with the QR code that leads to the explanation of how it is checked. PDF to print and SVG to edit.",
    maAfC: "Poster, light",
