    trustYes: "Yes", trustNo: "No", trustUnsure: "Not sure",
    trustSend: "Send response", trustSending: "Sending…",
    trustReceived: "Response received. Thank you",
    trustUnknown: "We do not know whether your response was saved. Retrying could count it twice.",
    trustRetry: "Retry: could count twice",
    trustBlocked: "The service is unavailable. We did not send your response.",
    tmTrust: "The optional trust-response service is off. When it is turned on, after checking a result you will be able to answer Yes, No or Not sure. Only totals per day will be stored, with the answer and the draw it refers to (its public number, which is already on Stellar), with no names, list, account, page address or the time you answered. Cloudflare receives the request, and the IP address is only used to limit how many arrive per hour, without storing it. If your browser asks not to be tracked, nothing is sent, and nothing is sent from the demo or a rehearsal either. This browser remembers that you already answered that draw, without sending that mark anywhere. One answer is counted, not one distinct person. If the confirmation does not arrive, the answer may have been saved anyway, and retrying would count it twice. When it is turned on, this page will say so, with its date.",
    vQuieroComprobar: "I want to check it", vChecks: "What was checked", vResult: "Who won", vList: "The sealed list",
    vCuentaPart: "{n} people, {k} entries", vEntriesDe: "{k} entries",
    vHow: "Run it again with your own tools",
    vHowIntro: "You don't have to trust this page. These are the exact steps, with this draw's values:",
    vProtocol: "The whole protocol ↗", vBack: "← Run a draw with Tinkazo",
    vRound: "See the public round ↗", vContract: "See the contract ↗",
    vWorking: "Checking the draw", vWorkingKicker: "One second",
    vVerdictOkKicker: "It all adds up", vVerdictBadKicker: "Something doesn't add up",
    vVerdictOkChain: "This draw checks out and it's on Stellar",
    vVerdictOkChainDetail: "We ran it again here and it matches what the contract recorded. That record stays there even if Tinkazo disappears, and anyone can read it.",
    vVerdictOkChainDetailTest: "We ran it again here and it matches what the contract recorded. It is on testnet, Stellar's test network, which gets wiped on December 16, 2026: until then, anyone can read that record.",
    vChainMissing: "the contract has no such draw",
    vVerdictMissing: "It's not on the chain",
    vVerdictMissingDetail: "The math adds up, but the contract has no record of this draw. It may be a wiped test network (testnet is wiped on December 16, 2026), an archived record or a number that doesn't exist. To check it against Stellar's history you need the code of the seal transaction, and older links don't carry it. Without that record, nobody vouches that this is the sealed list.",
    vVerdictBad: "This draw doesn't add up",
    vCannotFinish: "Couldn't finish checking",
    vNoProof: "This link carries no draw",
    vNoProofDetail: "Ask whoever ran the draw for the full link, including everything after the hash sign.",
    vCheckList: "The list and its fingerprint", vCheckRound: "The round signature",
    vCheckSeed: "The seed comes from the signature", vCheckWinner: "The recomputed winner", vCheckOrden: "The recomputed order",
    vCheckChain: "The record on Stellar",
    vNotDrawnYet: "not drawn on chain yet",
    vChainUnreachable: "couldn't read the contract",
    vSeals: "Other seals by this organizer, and of this list",
    vSealsWhy: "An organizer could seal the same list several times and publish only the result that suits them. Every seal is public, so here are theirs, all the ones still on chain. None of them repeats this draw's list or its head count.",
    vSealsSameCount: "same number of people",
    vSealsSameCountWhy: "There are other seals with the same number of people as this one. It may be another draw at the same event, or the same list with the names in another order, which gives a different fingerprint. If they are close in time, ask the organizer for the receipts.",
    vSealsOnly: "No other seals from this account are on chain.",
    vSealsAll: "all still on chain",
    vSealsMany: "there are more than fit here",
    vSealsAgain: "the same list, sealed again",
    vSealsAgainWhy: "This same list was sealed more than once. There may be a reason, like a draw that got stuck and was redone, but it is also how someone tries several rounds and publishes only the result that suits them. Ask the organizer for the receipts of all of them.",
    vSealsThis: "this draw",
