    vStepCounter: "counter",
    vVerdictUnknown: "I couldn't finish checking",
    vVerdictUnknownDetail: "The math adds up, but this draw says it is recorded on Stellar and I could not read that record. It may be the connection or an archived record. Until it can be read, nobody vouches that this is the sealed list: reload in a bit.",
    vRoundUnreachable: "couldn't fetch the beacon round",
    vListChanged: "The list in this link is not the one that was sealed. Someone changed it afterwards.",
    vBadSignature: "The round signature doesn't verify against the beacon's public key.",
    vMismatch: "The recomputed winner doesn't match the one on record.",
    // Strict verification (Oct 22, 2026): only the record of a Tinkazo contract running its code counts.
    vCheckOfficial: "It's Tinkazo's record",
    vCheckSealedFirst: "The list was sealed before the number",
    vSealedFirstDetail: "the number came out {s} s after the seal",
    vNotOfficialShort: "not Tinkazo's record",
    vAnchorBrokenShort: "the link doesn't say clearly where it is",
    vChainNever: "the contract never had that number",
    vVerdictNotOfficial: "This record isn't Tinkazo's",
    vVerdictNotOfficialDetail: "The link says the draw was recorded on Stellar, but somewhere that isn't Tinkazo's. Anyone can write a record like that, with whatever result they want, so it proves nothing.",
    vVerdictPending: "Sealed on Stellar, the result isn't recorded yet",
    vVerdictPendingDetail: "The list was sealed on Stellar before the number existed, and with that number the winner is the one you see. The result still has to be recorded: anyone can do it, and it comes out the same.",
    vAnchorBroken: "The link arrived incomplete: it says it is recorded on Stellar, but it lacks what's needed to find the record.",
    vChainNeverDetail: "The link names a draw that Tinkazo's record never had.",
    vCountChanged: "It was sealed with a different number of people than this list has: not everyone had a chance to win.",
    vRoundChanged: "This link uses a different public number than the one that was sealed.",
    vRoundEarly: "The deciding number already existed when the list was sealed.",
    vSeedChanged: "The number recorded on Stellar isn't the one the beacon published for that round.",
    vRecordOdd: "The record on Stellar doesn't add up with itself.",
    vTechContratoAjeno: "Network {red} and contract {c} are not among Tinkazo's (src/stellar/deployments.json).",
    vTechCodigoAjeno: "Contract {c} runs .wasm {w}, but Tinkazo's is {o}.",
    vTechAnclaDeforme: "The network, the contract or the draw number are missing or don't have the usual form.",
    vTechNumeroInexistente: "The contract is at draw {n}: draw {id} never existed.",
    vTechListaDeforme: "The list in the link isn't canonical: canonicalizing it changes it (repeats, blanks or text after a comma).",
    vTechListaCambiada: "Sealed fingerprint: {a}. Fingerprint of this list: {b}.",
    vTechCantidad: "The seal says {a} people and the list has {b}.",
    vTechRonda: "The seal says round {a} and the link, round {b}.",
    vTechRondaTemprana: "Round {r} was published {s} s after the seal: it has to be at least 30.",
    vTechFirma: "The signature doesn't verify against quicknet's public key for round {r}.",
    vTechFirmaRegistro: "The recorded signature isn't the one for round {r}.",
    vTechSemilla: "Recorded seed: {a}. Seed from the signature: {b}.",
    vTechGanadores: "Recorded winners: [{a}]. Recomputed: [{b}].",
    vTechRegistro: "The recorded seal and result don't add up with each other (number, round, status or number of winners).",
    vListLink: "The list in the link",
    vVerdictWaiting: "The number isn't out yet",
    vVerdictWaitingDetail: "The number that decides this draw comes out at {h}. Open the link again after that.",
    vVerdictSealedAgain: "It checks out, but this list was sealed more than once",
    vVerdictSealedAgainDetail: "What the contract recorded matches, but the same list has other seals (they are further down). There may be a reason, but it is also how someone tries several times and publishes only the convenient result: ask for the receipts of all of them.",
    vSealsNear: "another account, same number of people, almost the same time",
    vSealsNearWhy: "Another account sealed, at almost the same time, a draw with the same number of people. It may be another event, but it may also be the same list in another order, sealed from another account to keep the convenient result. If it matters to you, ask for both receipts.",
    vRetiredDetail: "The link points to a record Tinkazo no longer uses, and the draw was sealed there after it stopped being used. That record is still open and anyone can seal in it, so it proves nothing.",
    vTechContratoRetirado: "Contract {c} stopped being the site's at draw {n}, and this draw is {id}.",
    // When the contract no longer keeps the draw, the seal is checked against Stellar's history (protocol §7.1).
    // {m} is one of the next two: the network's fast memory no longer holds the draw (it was archived) or it couldn't be read just now.
    vVerdictOkHistoryDetail: "{m}. It was checked against its public history on Stellar: the seal is from {f} (code {c}) and the public number came out after it. We ran it again here and got the same name, so nobody could pick the result. The draw number in the link can't be checked this way: the draw is recognized by that date and that code.",
    vVerdictOkHistoryDetailTest: "{m}. It was checked against its public history on Stellar: the seal is from {f} (code {c}) and the public number came out after it. We ran it again here and got the same name, so nobody could pick the result. The draw number in the link can't be checked this way: the draw is recognized by that date and that code. It is on testnet, Stellar's test network, which gets wiped on December 16, 2026.",
    vHistMemoriaArchivada: "This draw is no longer in the network's fast memory",
    vHistMemoriaSinLeer: "I couldn't read this draw in the network's fast memory",
    vTx: "See the seal on Stellar ↗",
    vOfficialAddress: "its address is Tinkazo's",
    vChainFromHistory: "the seal is in the public history",
    vHistInvalidDetail: "The link cites a Stellar transaction that is not this draw's seal.",
    vHistDistinctDetail: "What the contract holds and what Stellar's public history says don't match for this draw, and both have to say the same thing.",
    // Why the history couldn't confirm a draw the contract no longer holds. None of them says it doesn't exist.
    vHistWhyDown: "The contract no longer holds this draw and I couldn't reach Stellar's public history, where it may still be. That doesn't mean it doesn't exist: try again in a bit.",
    vHistWhyOdd: "The contract no longer holds this draw and Stellar's public history answered something I couldn't understand. It may be a momentary hiccup: try again in a bit.",
    vHistWhyWindow: "The contract no longer holds this draw and the public Stellar history I check no longer keeps operations that old. That doesn't mean the draw doesn't exist, only that I can't check it from here. Stellar's complete history lives in its history archives and in explorers like stellar.expert: the seal transaction can be checked there, and the technical details say how.",
    vHistWhyNone: "The contract no longer holds this draw and the public Stellar history I check doesn't have that transaction. It may no longer keep it, or the link may have a mistake: I can't say either that it existed or that it didn't. An explorer like stellar.expert or Stellar's history archives can confirm it, and the technical details say how.",
